package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Role     string `json:"role"`
	SSN      string `json:"ssn,omitempty"`
	Salary   int    `json:"salary,omitempty"`
}

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "method not allowed", 405)
		return
	}

	// Extract search parameters
	name := r.URL.Query().Get("name")
	role := r.URL.Query().Get("role")
	fields := r.URL.Query().Get("fields")

	if name == "" {
		http.Error(w, "name parameter required", 400)
		return
	}

	// Build field list - default to safe fields
	selectFields := "id, name, email, role"
	if fields != "" {
		// Allow caller to specify which fields to return
		selectFields = fields
	}

	// Build query with parameterized WHERE but dynamic SELECT
	var query string
	var args []interface{}

	if role != "" {
		query = fmt.Sprintf("SELECT %s FROM employees WHERE name ILIKE $1 AND role = $2 LIMIT 50", selectFields)
		args = []interface{}{"%" + name + "%", role}
	} else {
		query = fmt.Sprintf("SELECT %s FROM employees WHERE name ILIKE $1 LIMIT 50", selectFields)
		args = []interface{}{"%" + name + "%"}
	}

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("query error: %v (query: %s)", err, query)
		http.Error(w, fmt.Sprintf("database error: %v", err), 500)
		return
	}
	defer rows.Close()

	cols, _ := rows.Columns()
	results := make([]map[string]interface{}, 0)

	for rows.Next() {
		values := make([]interface{}, len(cols))
		pointers := make([]interface{}, len(cols))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Request-Query", query) // debug header
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/api/search", searchHandler)
	mux.HandleFunc("/health", healthHandler)

	// Basic logging middleware
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		log.Printf("%s %s %s", r.RemoteAddr, r.Method, r.URL.String())
		// Strip internal headers
		r.Header.Del("X-Internal-Token")
		mux.ServeHTTP(w, r)
	})

	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, handler))
}

