func isFieldAllowed(field string, userRole string) bool {
	restricted := map[string][]string{
		"ssn":    {"admin", "hr"},
		"salary": {"admin", "hr", "finance"},
	}
	allowed, exists := restricted[strings.ToLower(field)]
	if !exists {
		return true
	}
	for _, r := range allowed {
		if r == userRole {
			return true
		}
	}
	return false
